-- schema-migration-posts-depth.sql
-- ============================================================================
-- DUYS Schema Migration: Posts Depth
-- Run this ONCE against your production database.
-- Adds pinning support + per-user deduped post views (poll/exclusive/schedule/link_previews tables already exist).

-- 1) Pinned posts (profile pinning — one active pin per author)
ALTER TABLE posts
  ADD COLUMN IF NOT EXISTS is_pinned BOOLEAN NOT NULL DEFAULT false;

ALTER TABLE posts
  ADD COLUMN IF NOT EXISTS pinned_at TIMESTAMP;

CREATE INDEX IF NOT EXISTS idx_posts_pinned ON posts(author_id, is_pinned)
  WHERE is_pinned = true;

-- 2) Deduped post views (one view per (post, user))
CREATE TABLE IF NOT EXISTS post_views (
  id SERIAL PRIMARY KEY,
  post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(post_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_post_views_post ON post_views(post_id);
CREATE INDEX IF NOT EXISTS idx_post_views_user ON post_views(user_id);

-- 3) Hashtag fuzzy lookup support (used by the search overlay + linkify)
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX IF NOT EXISTS idx_hashtags_tag_trgm ON hashtags USING gin (tag gin_trgm_ops);


-- ============================================================================
-- schema-migration-social-depth.sql
-- ============================================================================
-- DUYS Schema Migration: Social Depth (Phase 3)
-- Run this ONCE against your production database.
-- Adds group conversations, message reactions, blocks, mutes, message pins,
-- channel verifications, and live-room speaker/heart tracking. All tables are
-- additive — safe to run alongside existing schema.sql.

-- ============================================================================
-- 1) Message reactions (1:1 direct messages)
-- ============================================================================
CREATE TABLE IF NOT EXISTS message_reactions (
  id SERIAL PRIMARY KEY,
  message_id INTEGER NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  emoji VARCHAR(50) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(message_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_message_reactions_message ON message_reactions(message_id);

-- ============================================================================
-- 2) Message pins (pinned messages in a 1:1 conversation)
-- ============================================================================
CREATE TABLE IF NOT EXISTS message_pins (
  message_id INTEGER PRIMARY KEY REFERENCES messages(id) ON DELETE CASCADE,
  pinned_by INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  pinned_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- ============================================================================
-- 3) Conversation blocks & mutes for 1:1 messaging
-- ============================================================================
CREATE TABLE IF NOT EXISTS conversation_blocks (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  blocked_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(user_id, blocked_id)
);

CREATE INDEX IF NOT EXISTS idx_conversation_blocks_user ON conversation_blocks(user_id);
CREATE INDEX IF NOT EXISTS idx_conversation_blocks_blocked ON conversation_blocks(blocked_id);

CREATE TABLE IF NOT EXISTS conversation_mutes (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  conversation_id INTEGER NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(user_id, conversation_id)
);
-- ============================================================================
-- 4) Group conversations
-- ============================================================================
CREATE TABLE IF NOT EXISTS group_conversations (
  id SERIAL PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  description TEXT DEFAULT '',
  avatar_url TEXT DEFAULT '',
  created_by INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  invite_token VARCHAR(64) UNIQUE DEFAULT '',
  is_verified BOOLEAN NOT NULL DEFAULT false,
  verified_badge VARCHAR(20) DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_group_conversations_invite ON group_conversations(invite_token);
CREATE INDEX IF NOT EXISTS idx_group_conversations_created ON group_conversations(created_at DESC);

CREATE TABLE IF NOT EXISTS group_members (
  id SERIAL PRIMARY KEY,
  group_id INTEGER NOT NULL REFERENCES group_conversations(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role VARCHAR(20) NOT NULL DEFAULT 'member',
  muted BOOLEAN NOT NULL DEFAULT false,
  joined_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(group_id, user_id),
  CONSTRAINT valid_group_member_role CHECK (role IN ('owner', 'admin', 'member'))
);

CREATE INDEX IF NOT EXISTS idx_group_members_group ON group_members(group_id);
CREATE INDEX IF NOT EXISTS idx_group_members_user ON group_members(user_id);

CREATE TABLE IF NOT EXISTS group_messages (
  id SERIAL PRIMARY KEY,
  group_id INTEGER NOT NULL REFERENCES group_conversations(id) ON DELETE CASCADE,
  sender_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  body TEXT NOT NULL,
  reply_to INTEGER REFERENCES group_messages(id) ON DELETE SET NULL,
  read_at TIMESTAMP,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW(),
  deleted_at TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_group_messages_group ON group_messages(group_id, id DESC);
CREATE INDEX IF NOT EXISTS idx_group_messages_sender ON group_messages(sender_id);

CREATE TABLE IF NOT EXISTS group_message_reactions (
  id SERIAL PRIMARY KEY,
  message_id INTEGER NOT NULL REFERENCES group_messages(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  emoji VARCHAR(50) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(message_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_group_message_reactions_msg ON group_message_reactions(message_id);

-- ============================================================================
-- 5) Channel depth: mutes + verifications
-- ============================================================================
CREATE TABLE IF NOT EXISTS channel_mutes (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  channel_id INTEGER NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(user_id, channel_id)
);

CREATE INDEX IF NOT EXISTS idx_channel_mutes_user ON channel_mutes(user_id);

CREATE TABLE IF NOT EXISTS channel_verifications (
  id SERIAL PRIMARY KEY,
  channel_id INTEGER NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  badge VARCHAR(20) NOT NULL DEFAULT 'blue',
  status VARCHAR(20) NOT NULL DEFAULT 'pending',
  decided_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
  reason TEXT DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(channel_id, user_id),
  CONSTRAINT valid_channel_verify_status CHECK (status IN ('pending', 'approved', 'rejected'))
);

CREATE INDEX IF NOT EXISTS idx_channel_verifications_channel ON channel_verifications(channel_id);
CREATE INDEX IF NOT EXISTS idx_channel_verifications_user ON channel_verifications(user_id);
CREATE INDEX IF NOT EXISTS idx_channel_verifications_status ON channel_verifications(status);

-- ============================================================================
-- 6) Group verification (self-apply + admin review)
-- ============================================================================
CREATE TABLE IF NOT EXISTS group_verifications (
  id SERIAL PRIMARY KEY,
  group_id INTEGER NOT NULL REFERENCES group_conversations(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  badge VARCHAR(20) NOT NULL DEFAULT 'blue',
  status VARCHAR(20) NOT NULL DEFAULT 'pending',
  decided_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
  reason TEXT DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(group_id, user_id),
  CONSTRAINT valid_group_verify_status CHECK (status IN ('pending', 'approved', 'rejected'))
);

CREATE INDEX IF NOT EXISTS idx_group_verifications_group ON group_verifications(group_id);
CREATE INDEX IF NOT EXISTS idx_group_verifications_user ON group_verifications(user_id);
CREATE INDEX IF NOT EXISTS idx_group_verifications_status ON group_verifications(status);

-- ============================================================================
-- 7) Channel view tracking (parity with legacy /c/<handle>/view/<post_id>)
-- ============================================================================

-- ============================================================================
-- 8) Live Spaces: speakers + hearts
-- ============================================================================
CREATE TABLE IF NOT EXISTS room_speakers (
  id SERIAL PRIMARY KEY,
  room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  joined_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(room_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_room_speakers_room ON room_speakers(room_id);
CREATE INDEX IF NOT EXISTS idx_room_speakers_user ON room_speakers(user_id);

CREATE TABLE IF NOT EXISTS room_hearts (
  id SERIAL PRIMARY KEY,
  room_id INTEGER NOT NULL REFERENCES rooms(id) ON DELETE CASCADE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  count INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(room_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_room_hearts_room ON room_hearts(room_id);

-- ============================================================================
-- 9) WebRTC calls (signaling queue — server is a relay, not a TURN/STUN server)
-- ============================================================================
CREATE TABLE IF NOT EXISTS calls (
  id VARCHAR(64) PRIMARY KEY,
  room_id INTEGER REFERENCES rooms(id) ON DELETE SET NULL,
  conversation_id INTEGER REFERENCES conversations(id) ON DELETE SET NULL,
  caller_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind VARCHAR(20) NOT NULL DEFAULT 'voice',
  status VARCHAR(20) NOT NULL DEFAULT 'ringing',
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  ended_at TIMESTAMP,
  CONSTRAINT valid_call_kind CHECK (kind IN ('voice', 'video')),
  CONSTRAINT valid_call_status CHECK (status IN ('ringing', 'active', 'ended', 'declined'))
);

CREATE INDEX IF NOT EXISTS idx_calls_caller ON calls(caller_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_calls_status ON calls(status, created_at);

CREATE TABLE IF NOT EXISTS call_signals (
  id SERIAL PRIMARY KEY,
  call_id VARCHAR(64) NOT NULL REFERENCES calls(id) ON DELETE CASCADE,
  from_user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  to_user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind VARCHAR(20) NOT NULL,
  data TEXT NOT NULL,
  emitted_at TIMESTAMP NOT NULL DEFAULT NOW(),
  delivered BOOLEAN NOT NULL DEFAULT false
);

CREATE INDEX IF NOT EXISTS idx_call_signals_call ON call_signals(call_id);
CREATE INDEX IF NOT EXISTS idx_call_signals_to ON call_signals(to_user_id, delivered);


-- ============================================================================
-- schema-migration-economy.sql
-- ============================================================================
-- DUYS Schema Migration: Economy & Monetization
-- Run this ONCE against your production database.
-- Adds ledgers, ad-earnings, token claims, tips, shop listings/purchases
-- and vault swaps. Existing tables (users.points, boosts, referrals,
-- transactions, wallet_addresses) are reused.

-- 1) Points & token ledger (reason-tagged deltas)
CREATE TABLE IF NOT EXISTS point_ledger (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  delta NUMERIC(15, 4) NOT NULL,
  reason VARCHAR(100) NOT NULL,
  ref VARCHAR(255) DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_point_ledger_user ON point_ledger(user_id, id DESC);
CREATE INDEX IF NOT EXISTS idx_point_ledger_reason ON point_ledger(reason);

-- 2) Rewarded-ad tracking (HypeLab)
CREATE TABLE IF NOT EXISTS ad_views (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  reward INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_ad_views_user ON ad_views(user_id, created_at DESC);

CREATE TABLE IF NOT EXISTS hypelab_events (
  id SERIAL PRIMARY KEY,
  event_id VARCHAR(255) NOT NULL UNIQUE,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  reward INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

-- 3) Points -> DUYS token claims
CREATE TABLE IF NOT EXISTS token_claims (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  points_used INTEGER NOT NULL,
  tokens NUMERIC(15, 6) NOT NULL,
  status VARCHAR(50) NOT NULL DEFAULT 'pending',
  tx_hash VARCHAR(255) DEFAULT '',
  error_msg TEXT DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  CONSTRAINT valid_claim_status CHECK (status IN ('pending', 'confirmed', 'failed', 'voided'))
);

CREATE INDEX IF NOT EXISTS idx_token_claims_user ON token_claims(user_id, created_at DESC);

-- 4) Tips (points and/or DUYS)
CREATE TABLE IF NOT EXISTS tips (
  id SERIAL PRIMARY KEY,
  sender_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  recipient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  post_id INTEGER REFERENCES posts(id) ON DELETE SET NULL,
  amount_points INTEGER NOT NULL DEFAULT 0,
  amount_duys NUMERIC(15, 6) NOT NULL DEFAULT 0,
  message VARCHAR(280) DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  CONSTRAINT tips_nonzero CHECK (amount_points > 0 OR amount_duys > 0)
);

CREATE INDEX IF NOT EXISTS idx_tips_sender ON tips(sender_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tips_recipient ON tips(recipient_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tips_post ON tips(post_id);
-- 5) Creator shop (verified users sell downloadable files for DUYS)
CREATE TABLE IF NOT EXISTS shop_listings (
  id SERIAL PRIMARY KEY,
  seller_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title VARCHAR(128) NOT NULL,
  description TEXT DEFAULT '',
  file_key VARCHAR(500) NOT NULL,
  file_url TEXT NOT NULL,
  file_name VARCHAR(255) DEFAULT '',
  price_duys NUMERIC(15, 6) NOT NULL DEFAULT 0,
  active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMP NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_shop_listings_seller ON shop_listings(seller_id, id DESC);
CREATE INDEX IF NOT EXISTS idx_shop_listings_active ON shop_listings(active);

CREATE TABLE IF NOT EXISTS shop_purchases (
  id SERIAL PRIMARY KEY,
  buyer_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  listing_id INTEGER NOT NULL REFERENCES shop_listings(id) ON DELETE CASCADE,
  paid NUMERIC(15, 6) NOT NULL DEFAULT 0,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  UNIQUE(buyer_id, listing_id)
);

CREATE INDEX IF NOT EXISTS idx_shop_purchases_buyer ON shop_purchases(buyer_id);
CREATE INDEX IF NOT EXISTS idx_shop_purchases_listing ON shop_purchases(listing_id);

-- 6) Vault swaps (Buy/Sell DUYS <-> USDT, deposit-based settlement)
CREATE TABLE IF NOT EXISTS swaps (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  side VARCHAR(20) NOT NULL,
  from_token VARCHAR(20) NOT NULL,
  to_token VARCHAR(20) NOT NULL,
  from_amount NUMERIC(18, 8) NOT NULL,
  to_amount NUMERIC(18, 8) NOT NULL,
  rate NUMERIC(18, 10) NOT NULL DEFAULT 0,
  spread NUMERIC(10, 4) NOT NULL DEFAULT 0,
  user_address VARCHAR(255) DEFAULT '',
  deposit_token VARCHAR(20) NOT NULL DEFAULT '',
  status VARCHAR(50) NOT NULL DEFAULT 'awaiting_deposit',
  deposit_tx VARCHAR(255) DEFAULT '',
  payout_tx VARCHAR(255) DEFAULT '',
  error_msg TEXT DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMP NOT NULL DEFAULT NOW(),
  CONSTRAINT valid_swap_side CHECK (side IN ('buy', 'sell', 'transfer')),
  CONSTRAINT valid_swap_status CHECK (status IN
    ('awaiting_deposit', 'deposit_seen', 'settling', 'completed', 'expired', 'failed'))
);

CREATE INDEX IF NOT EXISTS idx_swaps_user ON swaps(user_id, id DESC);
CREATE INDEX IF NOT EXISTS idx_swaps_status ON swaps(status);

-- 7) Economy settings (admin-tunable via app_config)
INSERT INTO app_config (key, value, description) VALUES
  ('points_ad_reward', '10', 'Points awarded per rewarded ad view'),
  ('daily_ad_cap', '50', 'Max rewarded ad completions per user per day'),
  ('claim_points_per_token', '10', 'Points required for 1 DUYS claim'),
  ('claim_min_points', '100', 'Minimum points to start a claim'),
  ('claim_max_daily', '1', 'Max claims per day (regular users)'),
  ('claim_max_daily_verified', '3', 'Max claims per day (verified users)'),
  ('points_referral_bonus', '100', 'Points credited when a referred user signs up'),
  ('referral_earn_percent', '0.01', 'Referrer earns this share of referred users earnings'),
  ('fee_usd_boost_per_day', '1.00', 'USD price per boost-day'),
  ('swap_buy_enabled', 'true', 'Enable DUYS buy swaps'),
  ('swap_sell_enabled', 'true', 'Enable DUYS sell swaps'),
  ('token_price_override_enabled', 'false', 'Use the fixed token price below'),
  ('token_price_override_rate', '0', 'Fixed DUYS-per-USDT rate when override is on')
ON CONFLICT (key) DO NOTHING;

-- 8) Trigger for swaps.updated_at
DROP TRIGGER IF EXISTS swaps_updated_at ON swaps;
DROP TRIGGER IF EXISTS swaps_updated_at ON swaps;
CREATE TRIGGER swaps_updated_at BEFORE UPDATE ON swaps
  FOR EACH ROW EXECUTE FUNCTION update_timestamp();


-- ============================================================================
-- schema-settings-migration.sql
-- ============================================================================
-- DUYS Schema Migration: Settings, Privacy, Blocked Users
-- Run this ONCE against your production database (in addition to schema.sql).

-- Privacy columns for users
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_private BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE users ADD COLUMN IF NOT EXISTS who_can_message VARCHAR(20) NOT NULL DEFAULT 'everyone';
ALTER TABLE users ADD COLUMN IF NOT EXISTS show_online_status BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE users ADD COLUMN IF NOT EXISTS push_notifications JSONB NOT NULL DEFAULT '{}'::jsonb;

-- Blocked users
CREATE TABLE IF NOT EXISTS blocked_users (
  blocker_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  blocked_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  PRIMARY KEY (blocker_id, blocked_id),
  CONSTRAINT no_self_block CHECK (blocker_id != blocked_id)
);

CREATE INDEX IF NOT EXISTS idx_blocked_users_blocker ON blocked_users(blocker_id);
CREATE INDEX IF NOT EXISTS idx_blocked_users_blocked ON blocked_users(blocked_id);

-- Data export tracking
CREATE TABLE IF NOT EXISTS data_exports (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  status VARCHAR(20) NOT NULL DEFAULT 'pending',
  file_url TEXT DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  completed_at TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_data_exports_user ON data_exports(user_id, created_at DESC);


-- ============================================================================
-- schema-migration-admin-depth.sql
-- ============================================================================
-- Phase 4: Admin & Verification depth
-- verification_requests: badge applications + face/id moderation queue
CREATE TABLE IF NOT EXISTS verification_requests (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type VARCHAR(50) NOT NULL,
  requested_badge VARCHAR(50) DEFAULT '',
  cost_paid INTEGER NOT NULL DEFAULT 0,
  status VARCHAR(50) NOT NULL DEFAULT 'pending',
  admin_notes TEXT DEFAULT '',
  reviewed_by INTEGER REFERENCES users(id),
  reviewed_at TIMESTAMP,
  created_at TIMESTAMP NOT NULL DEFAULT NOW(),
  CONSTRAINT valid_vr_type CHECK (type IN ('badge', 'face', 'id')),
  CONSTRAINT valid_vr_status CHECK (status IN ('pending', 'approved', 'rejected'))
);
CREATE INDEX IF NOT EXISTS idx_vr_user_type ON verification_requests(user_id, type);
CREATE INDEX IF NOT EXISTS idx_vr_status ON verification_requests(status);
CREATE INDEX IF NOT EXISTS idx_vr_created_at ON verification_requests(created_at DESC);

INSERT INTO feature_flags (key, enabled, description) VALUES
  ('badge_verification', true, 'Allow users to request verified badges'),
  ('face_verification', true, 'Allow users to submit face verification photos'),
  ('economy_controls', true, 'Allow admins to adjust user points/tokens')
ON CONFLICT DO NOTHING;


